const items = $input.all();
const domains = items.map(i => ({ id: i.json.id, domain: String(i.json.domain).trim() })).filter(d => d.domain);
return [{ json: {
  started_at: new Date().toISOString(),
  domain_count: domains.length,
  domains,
  domains_space: domains.map(d => d.domain).join(' '),
  domains_newline: domains.map(d => d.domain).join('\n')
}}];

const raw = ($input.first().json.stdout || '').trim();
let subs = raw.split('\n').map(s => s.trim().toLowerCase()).filter(s => /^[a-z0-9][a-z0-9.-]*\.[a-z]{2,}$/.test(s));
subs = [...new Set(subs)].slice(0, 40);
return [{ json: {
  subdomain_count: subs.length,
  subdomains: subs,
  subdomains_newline: subs.join('\n'),
  subdomains_list: subs.join(',')
}}];

const subs = ($input.first().json.subdomains || []).slice(0, 30);
const web = subs.map(s => `https://${s}`);
return [{ json: {
  subdomains: subs,
  subdomains_newline: subs.join('\n'),
  web_targets: web,
  targets_newline: web.join('\n'),
  target_count: web.length
}}];

const raw = $input.first().json.stdout || '';
const certs = [], expSoon = [], expired = [];
for (const line of raw.split('\n')) {
  const t = line.trim();
  if (!t.startsWith('{')) continue;
  try {
    const c = JSON.parse(t);
    let days = null;
    if (c.not_after) days = Math.floor((new Date(c.not_after) - new Date()) / 86400000);
    const isExp = days !== null && days < 0;
    const e = { host: c.host || '', common_name: c.subject_cn || '', san: c.subject_an || [], issuer: c.issuer_cn || '', not_after: c.not_after || '', days_until_expiry: days, is_expired: isExp, expiring_soon: days !== null && days >= 0 && days <= 30 };
    certs.push(e);
    if (e.expiring_soon) expSoon.push(e);
    if (isExp) expired.push(e);
  } catch (e) {}
}
return [{ json: { total_certs_scanned: certs.length, expiring_soon_count: expSoon.length, expired_count: expired.length, cert_results: certs, expiring_soon: expSoon, expired: expired } }];

const raw = $input.first().json.stdout || '';
const httpxPart = (raw.split('===HTTPX===')[1] || '').split('===NAABU===')[0] || '';
const naabuPart = (raw.split('===NAABU===')[1] || '').split('===SHODAN===')[0] || '';
const shodanPart = (raw.split('===SHODAN===')[1] || '').trim();
const assets = [];
let live = 0, openPorts = 0;
for (const l of httpxPart.split('\n')) { const t = l.trim(); if (!t.startsWith('{')) continue; try { const j = JSON.parse(t); live++; assets.push({ host: j.host || j.input || '', ip: j.host_ip || '', port: parseInt(j.port) || 0, scheme: j.scheme || '', status_code: j.status_code || 0, title: String(j.title || '').substring(0,200), webserver: j.webserver || '', tech: Array.isArray(j.tech) ? j.tech.join(',') : '', source: 'httpx' }); } catch (e) {} }
for (const l of naabuPart.split('\n')) { const t = l.trim(); if (!t.startsWith('{')) continue; try { const j = JSON.parse(t); openPorts++; assets.push({ host: j.host || '', ip: j.ip || '', port: j.port || 0, scheme: '', status_code: 0, title: '', webserver: '', tech: '', source: 'naabu' }); } catch (e) {} }
let shodan = null;
try { const sj = JSON.parse(shodanPart); if (sj && sj.ip_str) { shodan = { ip: sj.ip_str, org: sj.org || '', os: sj.os || '', ports: sj.ports || [] }; assets.push({ host: (sj.hostnames || [])[0] || '', ip: sj.ip_str, port: (sj.ports || [])[0] || 0, scheme: '', status_code: 0, title: String(sj.org || '').substring(0,200), webserver: '', tech: 'shodan', source: 'shodan' }); } } catch (e) {}
return [{ json: { live_hosts: live, open_ports: openPorts, assets, shodan } }];

const raw = $input.first().json.stdout || '';
const all = [], crit = [], high = [], med = [];
for (const line of raw.split('\n')) {
  const t = line.trim();
  if (!t.startsWith('{')) continue;
  try {
    const f = JSON.parse(t);
    const info = f.info || {};
    const cls = info.classification || {};
    const e = { host: f.host || '', url: f['matched-at'] || f.url || '', template_id: f['template-id'] || '', template_name: info.name || '', severity: info.severity || '', description: String(info.description || '').substring(0,400), cve_id: cls['cve-id'] || [], cvss_score: cls['cvss-score'] || '', timestamp: f.timestamp || new Date().toISOString() };
    all.push(e);
    if (e.severity === 'critical') crit.push(e);
    else if (e.severity === 'high') high.push(e);
    else if (e.severity === 'medium') med.push(e);
  } catch (e) {}
}
return [{ json: { total_findings: all.length, critical_count: crit.length, high_count: high.length, medium_count: med.length, all_findings: all, critical_findings: crit, high_findings: high, medium_findings: med } }];

const raw = $input.first().json.stdout || '';
const findings = [];
for (const line of raw.split('\n')) {
  const t = line.trim();
  if (!t.startsWith('{')) continue;
  try {
    const r = JSON.parse(t);
    const vulns = r.vulnerabilities || [];
    for (const v of vulns) {
      findings.push({ host: r.host || '', ip: r.ip || '', port: r.port || '', banner: r.server_banner || '', osvdb_id: v.id || '', method: v.method || '', url: v.url || '', msg: v.msg || '' });
    }
  } catch (e) {}
}
return [{ json: { total_nikto_findings: findings.length, all_nikto_findings: findings } }];

const raw = $input.first().json.stdout || '';
const xss = [], confirmed = [];
for (const line of raw.split('\n')) {
  const t = line.trim();
  if (!t.startsWith('{')) continue;
  try {
    const r = JSON.parse(t);
    for (const v of (r.vulnerabilities || [])) {
      const e = { url: v.url || r.url || '', parameter: v.parameter || '', payload: v.payload || '', xss_type: v.type || 'reflected', severity: 'high', confirmed: v.confirmed || false };
      xss.push(e);
      if (e.confirmed) confirmed.push(e);
    }
  } catch (e) {}
}
return [{ json: { total_xss_findings: xss.length, confirmed_xss_count: confirmed.length, all_xss_findings: xss, confirmed_xss: confirmed } }];

const raw = $input.first().json.stdout || '';
const sqli = [], confirmed = [], dbmsFp = [];
const targetBlocks = raw.split('===SQLTARGET:');
for (const tb of targetBlocks) {
  if (!tb.trim()) continue;
  const urlMatch = tb.match(/^([^=]+)===/);
  const targetUrl = urlMatch ? urlMatch[1].trim() : '';
  let dbms = '';
  const dbmsM = tb.match(/back-end DBMS:\s*([^\n]+)/i);
  if (dbmsM) dbms = dbmsM[1].trim();
  const paramBlocks = tb.split(/Parameter:\s*/).slice(1);
  for (const pb of paramBlocks) {
    const nameM = pb.match(/^([^\(]+)\(([^\)]+)\)/);
    const param = nameM ? nameM[1].trim() : '';
    const typeM = pb.match(/Type:\s*([^\n]+)/);
    const titleM = pb.match(/Title:\s*([^\n]+)/);
    const payloadM = pb.match(/Payload:\s*([^\n]+)/);
    const e = { url: targetUrl, parameter: param, injection_type: typeM ? typeM[1].trim() : '', title: titleM ? titleM[1].trim() : '', payload: payloadM ? payloadM[1].trim() : '', dbms, dbms_version: '', technique: typeM ? typeM[1].trim() : '', severity: 'critical', confirmed: true };
    sqli.push(e); confirmed.push(e);
    if (dbms) dbmsFp.push({ software: dbms, version: '', host: targetUrl });
  }
}
return [{ json: { total_sqli_findings: sqli.length, confirmed_sqli_count: confirmed.length, all_sqli_findings: sqli, confirmed_sqli: confirmed, dbms_fingerprints: dbmsFp } }];

const d = $('Merge All Results').first().json;
const esc = s => String(s == null ? '' : s).replace(/'/g, "''");
const byKey = {};
const rows = [];
const add = (category, key, host, url, identifier, severity, title, finding) => {
  if (byKey[key]) return; byKey[key] = { category, host, url, identifier, severity, title, ...finding };
  rows.push(`('${esc(key)}','${category}','${esc(host)}','${esc(url)}','${esc(identifier)}','${esc(severity)}','${esc(String(title).substring(0,300))}')`);
};
for (const f of (d.all_findings || [])) add('vuln', `vuln|${f.host}|${f.template_id}|${f.url}`, f.host, f.url, f.template_id, f.severity, f.template_name, f);
for (const x of (d.all_xss_findings || [])) add('xss', `xss|${x.url}|${x.parameter}`, x.url, x.url, x.parameter, 'high', `XSS ${x.parameter}`, x);
for (const s of (d.all_sqli_findings || [])) add('sqli', `sqli|${s.url}|${s.parameter}`, s.url, s.url, s.parameter, 'critical', `SQLi ${s.parameter}`, s);
for (const c of (d.expiring_soon || [])) add('cert', `cert|${c.host}|${c.common_name}|soon`, c.host, '', c.common_name, c.days_until_expiry <= 7 ? 'high' : 'medium', `Cert expiring ${c.days_until_expiry}d`, c);
for (const c of (d.expired_certs || [])) add('cert', `cert|${c.host}|${c.common_name}|expired`, c.host, '', c.common_name, 'high', 'Cert expired', c);
let query;
if (rows.length > 0) {
  query = `INSERT INTO findings (finding_key, category, host, url, identifier, severity, title) VALUES ${rows.join(',')} ON CONFLICT (finding_key) DO UPDATE SET last_seen = now(), times_seen = findings.times_seen + 1, status = 'active' RETURNING finding_key, (xmax = 0) AS is_new;`;
} else {
  query = "SELECT NULL::text AS finding_key, false AS is_new WHERE false;";
}
return [{ json: { query, findings_by_key: byKey, total_keys: rows.length } }];

const rows = $input.all().map(i => i.json);
const map = $('Diff Prepare').first().json.findings_by_key || {};
const isNew = r => r.is_new === true || r.is_new === 't' || r.is_new === 1 || r.is_new === 'true';
const newKeys = rows.filter(isNew).map(r => r.finding_key);
const nf = newKeys.map(k => map[k]).filter(Boolean);
const pick = (cat, sev) => nf.filter(f => f.category === cat && (!sev || f.severity === sev));
const critical_findings = pick('vuln', 'critical');
const high_findings = pick('vuln', 'high');
const medium_findings = pick('vuln', 'medium');
const confirmed_xss = pick('xss');
const confirmed_sqli = pick('sqli');
const certNew = pick('cert');
const expiring_soon = certNew.filter(c => !c.is_expired);
const expired_certs = certNew.filter(c => c.is_expired);
const requires_alert = nf.length > 0;
return [{ json: {
  scan_timestamp: $('Merge All Results').first().json.scan_timestamp,
  new_findings_count: nf.length,
  requires_alert,
  critical_count: critical_findings.length,
  high_count: high_findings.length,
  medium_count: medium_findings.length,
  confirmed_xss_count: confirmed_xss.length,
  confirmed_sqli_count: confirmed_sqli.length,
  expiring_soon_count: expiring_soon.length,
  expired_count: expired_certs.length,
  critical_findings, high_findings, medium_findings, new_findings: nf,
  confirmed_xss, confirmed_sqli, expiring_soon, expired_certs,
  total_certs_scanned: $('Merge All Results').first().json.total_certs_scanned || 0
}}];

const d = $('Merge All Results').first().json;
const nd = $('Apply Diff').first().json;
const ts = d.scan_timestamp;
const startedAt = ($('Aggregate Domains').first().json.started_at) || ts;
const dur = Math.max(0, Math.round((new Date(ts) - new Date(startedAt))/1000));
const esc = s => String(s == null ? '' : s).replace(/'/g, "''");
const rows = [];
rows.push({ json: { query: `INSERT INTO scan_summary (scan_timestamp, total_certs_scanned, expiring_soon_count, expired_count, critical_count, high_count, medium_count, confirmed_xss_count, confirmed_sqli_count, total_exploits_found, new_findings_count, requires_alert, started_at, duration_seconds) VALUES ('${ts}', ${d.total_certs_scanned||0}, ${d.expiring_soon_count||0}, ${d.expired_count||0}, ${d.critical_count||0}, ${d.high_count||0}, ${d.medium_count||0}, ${d.confirmed_xss_count||0}, ${d.confirmed_sqli_count||0}, ${d.confirmed_sqli_count||0}, ${nd.new_findings_count||0}, ${nd.requires_alert||false}, '${startedAt}', ${dur});` } });
for (const f of (d.all_findings||[])) rows.push({ json: { query: `INSERT INTO scan_vulnerabilities (host,url,template_id,template_name,severity,description,scan_timestamp,requires_alert) VALUES ('${esc(f.host)}','${esc(f.url)}','${esc(f.template_id)}','${esc(f.template_name)}','${esc(f.severity)}','${esc(String(f.description).substring(0,500))}','${ts}',${f.severity==='critical'||f.severity==='high'}) ON CONFLICT DO NOTHING;` } });
for (const c of (d.all_cert_results||[])) rows.push({ json: { query: `INSERT INTO scan_certificates (host,common_name,issuer,not_after,days_until_expiry,is_expired,expiring_soon,scan_timestamp) VALUES ('${esc(c.host)}','${esc(c.common_name)}','${esc(c.issuer)}',${c.not_after?`'${esc(c.not_after)}'`:'NULL'},${c.days_until_expiry==null?'NULL':c.days_until_expiry},${c.is_expired||false},${c.expiring_soon||false},'${ts}') ON CONFLICT DO NOTHING;` } });
for (const x of (d.all_xss_findings||[])) rows.push({ json: { query: `INSERT INTO scan_xss (url,parameter,payload,xss_type,severity,confirmed,scan_timestamp) VALUES ('${esc(x.url)}','${esc(x.parameter)}','${esc(String(x.payload).substring(0,200))}','${esc(x.xss_type)}','high',${x.confirmed||false},'${ts}');` } });
for (const s of (d.all_sqli_findings||[])) rows.push({ json: { query: `INSERT INTO scan_sqli (url,parameter,injection_type,dbms,dbms_version,technique,severity,confirmed,scan_timestamp) VALUES ('${esc(s.url)}','${esc(s.parameter)}','${esc(s.injection_type)}','${esc(s.dbms)}','${esc(s.dbms_version)}','${esc(s.technique)}','critical',${s.confirmed||false},'${ts}');` } });
for (const a of (d.assets||[])) rows.push({ json: { query: `INSERT INTO scan_assets (host,ip,port,scheme,status_code,title,webserver,tech,source,scan_timestamp) VALUES ('${esc(a.host)}','${esc(a.ip)}',${a.port||0},'${esc(a.scheme)}',${a.status_code||0},'${esc(a.title)}','${esc(a.webserver)}','${esc(a.tech)}','${esc(a.source)}','${ts}');` } });
return rows.length ? rows : [{ json: { query: 'SELECT 1;' } }];

const data = $('Apply Diff').first().json;
const scanDate = new Date(data.scan_timestamp).toUTCString();
let vulnRows = '';
for (const v of (data.critical_findings||[])) vulnRows += `<tr style='background:#ffe6e6'><td>${v.host}</td><td>${v.template_name}</td><td><b style='color:red'>CRITICAL</b></td><td>${(v.cve_id||[]).join(', ')||'N/A'}</td></tr>`;
for (const v of (data.high_findings||[])) vulnRows += `<tr style='background:#fff3e6'><td>${v.host}</td><td>${v.template_name}</td><td><b style='color:orange'>HIGH</b></td><td>${(v.cve_id||[]).join(', ')||'N/A'}</td></tr>`;
let certRows = '';
for (const c of (data.expiring_soon||[])) certRows += `<tr style='background:#fffbe6'><td>${c.host}</td><td>${c.common_name}</td><td>${c.not_after}</td><td>${c.days_until_expiry} days</td></tr>`;
for (const c of (data.expired_certs||[])) certRows += `<tr style='background:#ffe6e6'><td>${c.host}</td><td>${c.common_name}</td><td>${c.not_after}</td><td><b style='color:red'>EXPIRED</b></td></tr>`;
let xssRows = '';
for (const x of (data.confirmed_xss||[])) xssRows += `<tr style='background:#ffe6e6'><td>${x.url}</td><td>${x.parameter}</td><td>${x.xss_type}</td></tr>`;
let sqliRows = '';
for (const s of (data.confirmed_sqli||[])) sqliRows += `<tr style='background:#ffe6e6'><td>${s.url}</td><td>${s.parameter}</td><td>${s.dbms}</td></tr>`;
const html = `<!DOCTYPE html><html><head><style>body{font-family:Arial;margin:20px;color:#333}.header{background:#1a1a2e;color:#fff;padding:20px;border-radius:8px}table{width:100%;border-collapse:collapse;margin:15px 0}th{background:#1a1a2e;color:#fff;padding:8px;text-align:left}td{padding:8px;border-bottom:1px solid #ddd}h3{color:#1a1a2e}</style></head><body><div class='header'><h1>EASM Security Scan - New Findings</h1><p>${scanDate}</p><p><b>${data.new_findings_count}</b> new finding(s) since last scan</p></div>${vulnRows?`<h3>Vulnerabilities</h3><table><tr><th>Host</th><th>Vulnerability</th><th>Severity</th><th>CVE</th></tr>${vulnRows}</table>`:''}${certRows?`<h3>Certificates</h3><table><tr><th>Host</th><th>CN</th><th>Expiry</th><th>Status</th></tr>${certRows}</table>`:''}${xssRows?`<h3>XSS</h3><table><tr><th>URL</th><th>Param</th><th>Type</th></tr>${xssRows}</table>`:''}${sqliRows?`<h3>SQL Injection</h3><table><tr><th>URL</th><th>Param</th><th>DBMS</th></tr>${sqliRows}</table>`:''}<p style='color:#888;font-size:12px'>Automated EASM pipeline · stateful diff engine suppressed already-known findings.</p></body></html>`;
let subject;
if ((data.critical_count||0) > 0 || (data.confirmed_sqli_count||0) > 0) subject = `[CRITICAL] EASM - ${data.critical_count} crit / ${data.confirmed_sqli_count} SQLi (new)`;
else if ((data.high_count||0) > 0 || (data.confirmed_xss_count||0) > 0) subject = `[HIGH] EASM - ${data.high_count} high / ${data.confirmed_xss_count} XSS (new)`;
else subject = `[NOTICE] EASM - ${data.new_findings_count} new finding(s)`;
return [{ json: { subject, html_body: html, discord_color: (data.critical_count||0)>0?15158332:(data.high_count||0)>0?15105570:16776960, critical_count: data.critical_count||0, high_count: data.high_count||0, medium_count: data.medium_count||0, confirmed_xss_count: data.confirmed_xss_count||0, confirmed_sqli_count: data.confirmed_sqli_count||0, expiring_soon_count: data.expiring_soon_count||0, expired_count: data.expired_count||0, new_findings_count: data.new_findings_count||0, scan_timestamp: data.scan_timestamp } }];

const d = $('Apply Diff').first().json;
const nf = d.new_findings || [];
const g = { high: [], medium: [], low: [] };
for (const f of nf) { const s = String(f.severity||'low').toLowerCase(); if (s==='high'||s==='critical') g.high.push(f); else if (s==='medium') g.medium.push(f); else g.low.push(f); }
const label = { high: 'High / Critical', medium: 'Medium', low: 'Low' };
const out = [];
for (const tier of ['high','medium','low']) {
  const fs = g[tier];
  if (!fs.length) continue;
  let rows = '';
  for (const f of fs) rows += `<tr><td>${f.category}</td><td><b>${f.severity}</b></td><td>${f.host||''}</td><td>${f.title||f.identifier||''}</td></tr>`;
  const html = `<!DOCTYPE html><html><body style='font-family:Arial;color:#222'><div style='background:#1a1a2e;color:#fff;padding:16px;border-radius:8px'><h2>EASM - ${label[tier]} findings</h2><p>${fs.length} new finding(s)</p></div><table style='width:100%;border-collapse:collapse;margin-top:12px' border='1' cellpadding='7'><tr style='background:#eee'><th>Category</th><th>Severity</th><th>Host</th><th>Finding</th></tr>${rows}</table><p style='color:#888;font-size:12px'>Automated EASM pipeline · ${d.scan_timestamp}</p></body></html>`;
  out.push({ json: { tier, count: fs.length, subject: `[EASM ${label[tier]}] ${fs.length} new finding(s)`, html_body: html } });
}
return out;

const nf = $('Apply Diff').first().json.new_findings || [];
const out = [];
for (const f of nf) {
  const sev = String(f.severity||'low').toLowerCase();
  const name = f.title || f.identifier || f.category;
  out.push({ json: { summary: `[${sev.toUpperCase()}] ${name} - ${f.host||''}`.substring(0,250), description: `Category: ${f.category}\nSeverity: ${sev}\nHost: ${f.host||''}\nURL: ${f.url||''}\nIdentifier: ${f.identifier||''}\n\nRaised automatically by the EASM pipeline.`, severity: sev, subtask_summary: `[${sev}] Remediate: ${name}`.substring(0,250) } });
}
return out;

const parents = $input.all();
const src = $('Prepare Jira Tickets').all();
const out = [];
for (let i = 0; i < parents.length; i++) {
  const p = parents[i].json;
  const key = p.key || (p.body && p.body.key);
  const s = src[i] ? src[i].json : {};
  if (!key) continue;
  out.push({ json: { parent_key: key, summary: s.subtask_summary || 'Remediate finding', severity: s.severity || 'low' } });
}
return out;
